def inspect_frames(mapping):
    frames = mapping.get('frames')
    ok = type(frames) is list and 0 <= len(frames) <= 2
    if ok:
        for frame in frames:
            if type(frame) is not dict or set(frame) != {'toggles'}:
                ok = False
                break
            toggles = frame['toggles']
            if not (type(toggles) is list and 0 <= len(toggles) <= 2):
                ok = False
                break
            for toggle in toggles:
                if type(toggle) is not bool:
                    ok = False
                    break
            if not ok:
                break
    result = {'ok': ok, 'frames': frames if ok else []}
